import {natureSites,careers} from './nature-data.js';
import {natureArt} from './nature-art.js';
import {everydayStories} from './everyday-data.js';
import {vietnamMainland} from './vietnam-geography.js';
import {schoolSources} from './school-data.js';
import {escapeHTML as esc} from './learning.js';
import {markActivity} from './journey-data.js';
const project=([lon,lat])=>[35+(lon-102)/15*610,28+(24-lat)/17*690];
export function createLivingWorld(root,api){
 let selected='stories',storyId='leaf',siteId='cucphuong',filter='all',careerId='conservation',value=70;
 root.innerHTML=`<header class="campus-heading"><div><span class="eyebrow">THẾ GIỚI SỐNG / TỪ TRANG SÁCH RA THIÊN NHIÊN</span><h1 data-page-heading tabindex="-1">Sinh học không ở đâu xa.<br><em>Ngay quanh bạn.</em></h1><p>Một chiếc lá, một khu rừng, một công việc tương lai. Bắt đầu bằng điều quen thuộc và đi theo bằng chứng.</p></div><a href="#/quests" class="campus-link">Nhận nhiệm vụ khám phá ↗</a></header><div class="campus-tabs" role="tablist" aria-label="Khám phá thế giới sống"><button type="button" id="world-tab-stories" role="tab" data-world-tab="stories" aria-controls="world-stories">Sinh học quanh ta</button><button type="button" id="world-tab-map" role="tab" data-world-tab="map" aria-controls="world-map">BioMap Việt Nam</button><button type="button" id="world-tab-careers" role="tab" data-world-tab="careers" aria-controls="world-careers">BioCareer</button></div><section id="world-stories" class="world-panel" role="tabpanel" aria-labelledby="world-tab-stories"><div class="everyday-picker">${everydayStories.map((s,i)=>`<button type="button" data-story="${s.id}"><span>0${i+1}</span><strong>${s.title}</strong><small>${s.tag}</small></button>`).join('')}</div><div class="everyday-workspace campus-card"><div class="everyday-visual"><div id="everyday-art"></div><label id="everyday-control-label" for="everyday-value"></label><input id="everyday-value" type="range" min="0" max="100" value="70"><p id="everyday-observation" role="status"></p><p class="campus-small">Sơ đồ và mức quy ước giúp so sánh cơ chế, không phải đo trên một mẫu vật hay cơ thể thật.</p></div><article class="everyday-story"><span class="campus-kicker" id="everyday-tag"></span><h2 id="everyday-title"></h2><p id="everyday-intro"></p><ol id="everyday-points"></ol><div class="everyday-question"><span>MỘT CÂU HỎI ĐỂ THỬ</span><p id="everyday-question"></p></div><div class="campus-button-row"><button type="button" id="everyday-lesson" class="campus-button">Đọc học liệu liên quan</button><button type="button" id="everyday-save" class="campus-button secondary">Giữ một câu hỏi vào sổ</button></div><details class="campus-source"><summary>Nguồn học liệu & đọc thêm</summary><div id="everyday-sources"></div></details></article></div></section><section id="world-map" class="world-panel" role="tabpanel" aria-labelledby="world-tab-map" hidden><div class="world-section-heading"><div><span class="campus-kicker">BIOMAP / ĐA DẠNG SINH HỌC VIỆT NAM</span><h2>Những nơi sự sống gặp nhau.</h2><p>Tám hồ sơ sinh thái được biên soạn từ nguồn bảo tồn và vườn quốc gia. Chọn điểm trên bản đồ hoặc danh sách để khám phá.</p></div><div class="map-filters" role="group" aria-label="Lọc sinh cảnh"><button type="button" data-map-filter="all">Tất cả</button><button type="button" data-map-filter="forest">Rừng</button><button type="button" data-map-filter="wetland">Đất ngập nước</button><button type="button" data-map-filter="marine">Biển đảo</button></div></div><div class="biomap-layout"><div class="biomap-atlas campus-card"><div id="biomap-view" class="biomap-view"></div><div id="biomap-site-list" class="biomap-site-list"></div><details class="campus-source"><summary>Đọc đúng bản đồ</summary><p>Điểm định hướng cho địa điểm đã chọn, không phải bản đồ hành chính hoặc ranh giới khu bảo tồn. Nền đất liền tổng quát hóa từ Natural Earth 1:110m; các đảo và quần đảo được chú thích khái quát, không dùng để xác định ranh giới hay dẫn đường.</p><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Nền Natural Earth · public domain ↗</a></details></div><article id="biomap-detail" class="biomap-detail campus-card"></article></div></section><section id="world-careers" class="world-panel" role="tabpanel" aria-labelledby="world-tab-careers" hidden><div class="world-section-heading"><div><span class="campus-kicker">BIOCAREER / TỪ ĐIỀU BẠN TÒ MÒ</span><h2>Một cách học. Nhiều con đường.</h2><p>Khám phá công việc, kiến thức nền và một hoạt động thử. Nguồn nghề nghiệp chính thống; không dùng mức lương hoặc câu chuyện phỏng vấn được tạo giả.</p></div></div><div id="career-picker" class="career-picker"></div><div id="career-detail" class="career-detail campus-card"></div></section>`;
 function sourcesHTML(items){return items.filter(Boolean).map(([title,url])=>`<a href="${url}" target="_blank" rel="noopener">${esc(title)} ↗</a>`).join('')}
 function drawEveryday(){const s=everydayStories.find(s=>s.id===storyId),host=root.querySelector('#everyday-art');let art='',observation='';
 if(s.id==='leaf'){const hue=38+value*.6;art=`<path d="M150 298Q160 100 480 70q-4 205-296 253Z" fill="hsl(${hue} 35% 55%)" stroke="#688250" stroke-width="3"/><path d="m140 340 270-200m-180 135-6-85m63 47 1-105m-3 106 108-6m-54-50 94-3" stroke="#d5dfad" stroke-width="3" fill="none"/>`;observation=`Diệp lục quy ước ${value}%. ${value<45?'Các màu vàng/cam được biểu diễn rõ hơn khi phần xanh giảm.':'Màu xanh đang chiếm ưu thế trong minh họa.'}`}
 else if(s.id==='osmosis'){const scale=.96-(value-50)*.004;art=`<rect x="165" y="75" width="300" height="255" rx="48" fill="#cadbbb" stroke="#89a873" stroke-width="9"/><g transform="translate(315 202) scale(${scale})"><rect x="-143" y="-122" width="286" height="244" rx="43" fill="#91bca3" stroke="#5a997b" stroke-width="3"/><ellipse cx="15" cy="-2" rx="85" ry="88" fill="#bdd8c4"/><circle cx="-88" cy="45" r="24" fill="#b3a4bc"/></g>`;observation=value>53?'Môi trường ngoài ưu trương trong mô hình: nước có xu hướng đi ra.':value<47?'Môi trường ngoài nhược trương trong mô hình: nước có xu hướng đi vào.':'Gần đẳng trương: không có dòng nước thuần đáng kể.'}
 else if(s.id==='sweat'){art=`<path d="M80 290q220-40 470 0v90H80Z" fill="#c8ad86"/><path d="M80 290q220-40 470 0" fill="none" stroke="#ac936f" stroke-width="5"/>${[0,1,2,3,4].map(i=>`<g class="evaporation-drop" style="--evap-speed:${1+value/30}s"><path d="M${155+i*75} 235q-24 30 0 39 24-9 0-39" fill="#8fbdb7"/><path d="M${155+i*75} 210v-60m-7 9 7-9 7 9" stroke="#7da69a" fill="none" stroke-width="2" opacity="${1-value/130}"/></g>`).join('')}`;observation=`Độ ẩm minh họa ${value}%. ${value>65?'Khả năng bay hơi được biểu diễn giảm.':'Không khí ít ẩm hơn tạo điều kiện thuận lợi hơn cho bay hơi, nếu các yếu tố khác tương tự.'}`}
 else if(s.id==='fruit'){art=`<path d="M155 102q-33 190 280 205-220 85-280-205Z" fill="hsl(${80-value*.38} 48% 63%)" stroke="#a9a35e" stroke-width="4"/><path d="M172 114q-7 135 222 176" fill="none" stroke="#e6dba1" stroke-width="8"/><path d="M457 95q65-22 82 52 22 99-70 92-86 4-76-82 7-68 64-62" fill="#b9a36f"/><path d="m455 95 13-40m0 16q23-31 47-12-23 25-47 12" stroke="#6a8e5d" fill="none" stroke-width="6"/>`;observation=`Giai đoạn minh họa ${Math.round(value/20)}/5. Màu quả là quy ước; không quy đổi sang số ngày hoặc nồng độ ethylene.`}
 else {art=`<g transform="translate(90 100)">${[0,1,2,3,4,5].map(i=>`<path d="M0 ${i*30}q200-40 440 0" fill="none" stroke="${i%2?'#c49a87':'#b08778'}" stroke-width="22"/>`).join('')}${value>45?'<g fill="#d4ba80" opacity=".8"><circle cx="170" cy="60" r="17"/><circle cx="240" cy="100" r="20"/><circle cx="320" cy="70" r="14"/></g>':''}</g>`;observation=value<35?'Đang so sánh cảm giác ngay trong hoặc ngay sau hoạt động.':value<75?'Mốc khái niệm: triệu chứng xuất hiện muộn sau hoạt động chưa quen.':'Cần phân biệt hiện tượng và xem xét thêm bằng chứng; thanh này không dự báo hồi phục.'}
 host.innerHTML=`<svg viewBox="0 0 630 400" role="img" aria-label="Minh họa ${esc(s.title)}">${art}</svg>`;root.querySelector('#everyday-observation').textContent=observation;
 }
 function story(){const s=everydayStories.find(s=>s.id===storyId);for(const [id,text] of [['everyday-tag',s.tag],['everyday-title',s.title],['everyday-intro',s.intro],['everyday-question',s.question],['everyday-control-label',s.control]])root.querySelector('#'+id).textContent=text;root.querySelector('#everyday-points').innerHTML=s.points.map((p,i)=>`<li><span>0${i+1}</span><p>${p}</p></li>`).join('');root.querySelector('#everyday-sources').innerHTML=sourcesHTML([s.source,s.extraSource,[`SGK ${schoolSources[s.grade].title} · NXBGDVN`,schoolSources[s.grade].url]]);root.querySelectorAll('[data-story]').forEach(b=>{const yes=b.dataset.story===storyId;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))});drawEveryday()}
 function map(){const ring=vietnamMainland.map(c=>project(c).map(n=>n.toFixed(1)).join(',')).join(' '),sites=natureSites.filter(s=>filter==='all'||s.kind===filter);root.querySelector('#biomap-view').innerHTML=`<svg viewBox="0 0 700 760" role="img" aria-label="BioMap: điểm định hướng sinh thái Việt Nam"><defs><linearGradient id="vietnam-land" x2="1" y2="1"><stop stop-color="#bad19c"/><stop offset="1" stop-color="#759873"/></linearGradient><pattern id="map-grid" width="70" height="70" patternUnits="userSpaceOnUse"><path d="M70 0H0v70" fill="none" stroke="#8eb7ab" stroke-opacity=".16"/></pattern></defs><rect width="700" height="760" rx="18" fill="#d5e6db"/><rect width="700" height="760" fill="url(#map-grid)"/><polygon points="${ring}" fill="url(#vietnam-land)" stroke="#6d9175" stroke-width="1.5"/><ellipse cx="${project([103.95,10.22])[0]}" cy="${project([103.95,10.22])[1]}" rx="6" ry="11" fill="#8faf85"/><ellipse cx="${project([106.64,8.7])[0]}" cy="${project([106.64,8.7])[1]}" rx="5" ry="7" fill="#8faf85"/><g class="map-island-labels" fill="#5a7b6b"><text x="${project([111,17])[0]}" y="${project([111,17])[1]}">QĐ. Hoàng Sa</text><text x="${project([113,9.5])[0]}" y="${project([113,9.5])[1]}">QĐ. Trường Sa</text><text x="510" y="400" font-size="17" letter-spacing="2" opacity=".65">BIỂN ĐÔNG</text>${[[112,16.5],[112.5,16],[114,10],[114.5,9.4],[113.6,10.8]].map(c=>`<circle cx="${project(c)[0]}" cy="${project(c)[1]}" r="2.5"/>`).join('')}</g>${sites.map((s,i)=>{const [x,y]=project([s.lon,s.lat]);return `<g class="map-marker ${siteId===s.id?'selected':''}" data-map-site="${s.id}" tabindex="0" role="button" aria-label="Khám phá ${s.name}"><circle class="marker-halo" cx="${x}" cy="${y}" r="18"/><circle cx="${x}" cy="${y}" r="11"/><text x="${x}" y="${y+4}" text-anchor="middle">${natureSites.indexOf(s)+1}</text><title>${s.name} · ${s.habitat}</title></g>`}).join('')}<text x="25" y="735" font-size="12" fill="#4d7562">VNS / 8 ĐIỂM NHÌN SINH THÁI · TỌA ĐỘ ĐỊNH HƯỚNG</text></svg>`;
 root.querySelector('#biomap-site-list').innerHTML=sites.map(s=>`<button type="button" data-map-site="${s.id}" aria-pressed="${s.id===siteId}"><span>${natureSites.indexOf(s)+1}</span><b>${s.name}</b><small>${s.habitat}</small></button>`).join('');root.querySelectorAll('[data-map-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.mapFilter===filter);b.setAttribute('aria-pressed',String(b.dataset.mapFilter===filter))});const s=natureSites.find(s=>s.id===siteId);root.querySelector('#biomap-detail').innerHTML=`<div class="biomap-habitat-art">${natureArt(s.kind,`Minh họa sinh cảnh ${s.habitat}`)}</div><span class="campus-kicker">${s.region}</span><h2>${s.name}</h2><span class="habitat-tag">${s.habitat}</span><p>${s.summary}</p><h3>Sự sống đặc trưng</h3><div class="map-species">${s.species.map(a=>`<div><strong>${a.name}</strong><p>${a.text}</p></div>`).join('')}</div><h3>Nhìn cả tác động lẫn giải pháp</h3><p>${s.pressures}</p><p>${s.conservation}</p><div class="map-question"><span class="campus-kicker">NẾU BẠN LÀ NGƯỜI KHÁM PHÁ</span><p>${s.question}</p><div class="campus-answers">${s.actionOptions.map((text,i)=>`<button type="button" data-map-answer="${i}">${text}</button>`).join('')}</div><p id="map-feedback" role="status"></p></div><div class="campus-button-row"><button type="button" id="map-save" class="campus-button">Lưu hồ sơ sinh thái</button><a href="#/quests" class="campus-link">Thử nhiệm vụ bảo tồn →</a></div><details class="campus-source"><summary>Nguồn hồ sơ & tọa độ</summary><p>${s.coordinateNote}</p>${sourcesHTML([s.source,...s.extraSources])}<p>Thông tin được đối chiếu ngày 06/11/2026. Không phải bản tin quan trắc, danh mục mọi loài hoặc xếp hạng nguy cấp cập nhật trực tiếp.</p></details>`;
 }
 function career(){const c=careers.find(c=>c.id===careerId)||careers[0];careerId=c.id;root.querySelector('#career-picker').innerHTML=careers.map((c,i)=>`<button type="button" data-career="${c.id}" aria-pressed="${careerId===c.id}"><span>0${i+1}</span><strong>${c.name}</strong><small>${c.tag}</small></button>`).join('');root.querySelector('#career-detail').innerHTML=`<div class="career-art">${natureArt(c.id==='marine'?'marine':c.id==='biotech'||c.id==='laboratory'?'wetland':'forest','Minh họa sự sống và hoạt động khám phá')}</div><div class="career-copy"><span class="campus-kicker">${c.tag}</span><h2>${c.name}</h2><p>${c.work}</p><div class="career-learning"><div><h3>Kiến thức nền</h3><ul>${c.subjects.map(s=>`<li>${s}</li>`).join('')}</ul></div><div><h3>Kỹ năng cần rèn</h3><ul>${c.skills.map(s=>`<li>${s}</li>`).join('')}</ul></div></div><div class="career-trial"><span class="campus-kicker">THỬ MỘT VIỆC NHỎ</span><p>${c.trial.label}</p><button id="career-trial" type="button" class="campus-button">Bắt đầu trải nghiệm →</button><button id="career-save" type="button" class="campus-button secondary">Lưu con đường tôi tò mò</button></div><details class="campus-source"><summary>Nguồn nghề nghiệp & chương trình tham khảo</summary>${sourcesHTML([c.source,c.vietnamSource])}<p>Nguồn quốc tế mô tả công việc; không áp dụng mức lương hoặc điều kiện hành nghề nước ngoài cho Việt Nam. Liên kết trường để tìm hiểu, không phải cam kết tuyển sinh hay kiểm định của VNScape.</p></details></div>`}
 function select(tab){selected=['stories','map','careers'].includes(tab)?tab:'stories';root.querySelectorAll('[data-world-tab]').forEach(b=>{const yes=b.dataset.worldTab===selected;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1});root.querySelectorAll('.world-panel').forEach(p=>p.hidden=p.id!=='world-'+selected);if(selected==='map')map();else if(selected==='careers')career();else story()}
 root.querySelector('#everyday-value').addEventListener('input',e=>{value=Number(e.target.value);drawEveryday()});root.querySelector('#everyday-lesson').addEventListener('click',()=>api.openLesson(everydayStories.find(s=>s.id===storyId).lesson));root.querySelector('#everyday-save').addEventListener('click',()=>{const s=everydayStories.find(s=>s.id===storyId);markActivity(api.getState());api.addNote(`Sinh học quanh ta: ${s.title}`,`${s.intro}\n\nĐiều tôi muốn tìm hiểu: ${s.question}\n\nQuan sát mô hình: ${root.querySelector('#everyday-observation').textContent}\n\nSuy nghĩ của tôi:\n\nNguồn: ${s.source[1]}`);api.toast('Đã giữ một câu hỏi từ đời sống vào sổ tay.')});
 root.addEventListener('click',e=>{const b=e.target.closest('button,[data-map-site]');if(!b)return;if(b.dataset.worldTab)api.navigate('world/'+b.dataset.worldTab);else if(b.dataset.story){storyId=b.dataset.story;story()}else if(b.dataset.mapFilter){filter=b.dataset.mapFilter;const list=natureSites.filter(s=>filter==='all'||s.kind===filter);if(!list.some(s=>s.id===siteId))siteId=list[0].id;map()}else if(b.dataset.mapSite){siteId=b.dataset.mapSite;map()}else if(b.dataset.mapAnswer!==undefined){const s=natureSites.find(s=>s.id===siteId),yes=Number(b.dataset.mapAnswer)===s.correctAction;api.feedback?.(b,yes);root.querySelector('#map-feedback').textContent=yes?s.actionFeedback:'Hãy xem tác động tới sinh cảnh và các loài; chọn một hành động phù hợp với nguồn bảo tồn.';if(yes){const state=api.getState();if(!state.visitedSites.includes(siteId))state.visitedSites.push(siteId);markActivity(state);api.persist()}}else if(b.id==='map-save'){const s=natureSites.find(s=>s.id===siteId);markActivity(api.getState());api.addNote(`BioMap: ${s.name}`,`${s.habitat}\n${s.summary}\n\nSự sống: ${s.species.map(a=>a.name).join(', ')}\n\nBảo tồn: ${s.conservation}\n\nCâu hỏi: ${s.question}\n\nNguồn: ${s.source[1]}\nĐiểm định hướng, không phải ranh giới khu bảo tồn.`);api.toast('Đã lưu một hồ sơ sinh thái.')}else if(b.dataset.career){careerId=b.dataset.career;career()}else if(b.id==='career-save'){const c=careers.find(c=>c.id===careerId);api.addNote(`BioCareer: ${c.name}`,`${c.work}\n\nKiến thức: ${c.subjects.join(', ')}\nKỹ năng: ${c.skills.join(', ')}\n\nHoạt động tôi muốn thử: ${c.trial.label}\n\nNguồn: ${c.source[1]}`);api.toast('Đã giữ một hướng đi để tìm hiểu thêm.')}else if(b.id==='career-trial'){const c=careers.find(c=>c.id===careerId);if(c.trial.route==='lab')api.navigate('lab/'+(c.trial.tab||'stations'));else if(c.trial.route==='studio')api.navigate('studio/'+(c.trial.tab||'gene'));else api.navigate(c.trial.route==='world'?'world/map':c.trial.route)}});
 root.addEventListener('keydown',e=>{const marker=e.target.closest('[data-map-site]');if(marker&&['Enter',' '].includes(e.key)){e.preventDefault();siteId=marker.dataset.mapSite;map()}});root.querySelector('.campus-tabs').addEventListener('keydown',e=>{const ids=['stories','map','careers'];if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?2:(ids.indexOf(selected)+(e.key==='ArrowRight'?1:2))%3;api.navigate('world/'+ids[index]);root.querySelector('#world-tab-'+ids[index]).focus()}});select('stories');return {select,setActive(){}};
}
